/* Nota Bab 2 ikut buku teks Matematik T2 KSSM. Dijana skrip; jangan sunting dengan tangan. */
window.SUBS=[{"no": "2.1", "name": "Kembangan", "col": "#38BDF8"}, {"no": "2.2", "name": "Pemfaktoran", "col": "#34D399"}, {"no": "2.3", "name": "Ungkapan Algebra dan Hukum Operasi Asas Aritmetik", "col": "#A78BFA"}];
window.SLIDES=[{"sub": "2.1", "n": 1, "N": 8, "kicker": "DEFINISI", "title": "Kembangan ungkapan algebra", "body": "<div class=\"sl-def\" style=\"--c:#38BDF8\"><p><b>Kembangan ungkapan algebra</b> bermaksud hasil pendaraban satu atau dua ungkapan dalam kurungan.</p></div><ul class=\"sl-bul\" style=\"--c:#38BDF8\"><li><span>Apabila melakukan kembangan ungkapan algebra, setiap sebutan dalam tanda kurungan mesti didarabkan dengan sebutan di luar kurungan.</span></li><li><span>Ungkapan algebra ialah ungkapan yang menggabungkan nombor, pemboleh ubah atau simbol matematik lain dengan operasi. Misalnya, 2<i>a</i> + 5.</span></li></ul>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Luas segi empat tepat x darab (x + 3)\"><rect x=\"60\" y=\"110\" width=\"250\" height=\"230\" fill=\"#38BDF833\" stroke=\"#38BDF8\" stroke-width=\"3\"/><rect x=\"310\" y=\"110\" width=\"120\" height=\"230\" fill=\"#FBBF2433\" stroke=\"#FBBF24\" stroke-width=\"3\"/><text x=\"185.0\" y=\"95.0\" fill=\"#38BDF8\" font-family=\"Inter, sans-serif\" font-size=\"22\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">x</tspan></text><text x=\"370.0\" y=\"95.0\" fill=\"#FBBF24\" font-family=\"Inter, sans-serif\" font-size=\"22\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"40.0\" y=\"232.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"22\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">x</tspan></text><text x=\"185.0\" y=\"235.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"26\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">x</tspan>²</text><text x=\"370.0\" y=\"235.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"26\" font-weight=\"700\" text-anchor=\"middle\">3<tspan font-style=\"italic\">x</tspan></text><g class=\"rv\"><text x=\"245.0\" y=\"400.0\" fill=\"#34D399\" font-family=\"Inter, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">x</tspan>(<tspan font-style=\"italic\">x</tspan> + 3) = <tspan font-style=\"italic\">x</tspan>² + 3<tspan font-style=\"italic\">x</tspan></text></g></svg>", "full": ""}, {"sub": "2.1", "n": 2, "N": 8, "kicker": "CONTOH 1", "title": "Kembangan satu ungkapan", "body": "<p class=\"sl-p\">Kembangkan setiap ungkapan berikut.</p><ul class=\"sl-bul\" style=\"--c:#38BDF8\"><li><span>(a) 4(2 + 5<i>w</i>)</span></li><li><span>(b) 2<i>p</i>(<i>p</i> − 3<i>q</i>)</span></li><li><span>(c) −3<i>k</i>(<i>m</i> + 4)</span></li><li><span>(d) −<span class=\"fr\"><span>3<i>y</i></span><span>4</span></span>(8<i>y</i> − 4<i>z</i> + 12<i>x</i>)</span></li></ul><div class=\"sl-note\"><b>Imbas kembali:</b> (+) × (+) = + &nbsp; (+) × (−) = − &nbsp; (−) × (+) = − &nbsp; (−) × (−) = +</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#38BDF8\">(a)</b> <div class=\"rv\">4(2 + 5<i>w</i>)</div><div class=\"rv\">= (4 × 2) + (4 × 5<i>w</i>)</div><div class=\"rv\">= 8 + 20<i>w</i></div></div><div><b style=\"color:#38BDF8\">(b)</b> <div class=\"rv\">2<i>p</i>(<i>p</i> − 3<i>q</i>)</div><div class=\"rv\">= (2<i>p</i> × <i>p</i>) + [2<i>p</i> × (−3<i>q</i>)]</div><div class=\"rv\">= 2<i>p</i>² − 6<i>pq</i></div></div><div><b style=\"color:#38BDF8\">(c)</b> <div class=\"rv\">−3<i>k</i>(<i>m</i> + 4)</div><div class=\"rv\">= (−3<i>k</i> × <i>m</i>) + (−3<i>k</i> × 4)</div><div class=\"rv\">= −3<i>km</i> − 12<i>k</i></div></div><div><b style=\"color:#38BDF8\">(d)</b> <div class=\"rv\">= (−<span class=\"fr\"><span>3<i>y</i></span><span>4</span></span> × 8<i>y</i>) + [−<span class=\"fr\"><span>3<i>y</i></span><span>4</span></span> × (−4<i>z</i>)] + (−<span class=\"fr\"><span>3<i>y</i></span><span>4</span></span> × 12<i>x</i>)</div><div class=\"rv\">= −6<i>y</i>² + 3<i>yz</i> − 9<i>xy</i></div></div></div>", "full": ""}, {"sub": "2.1", "n": 3, "N": 8, "kicker": "KONSEP", "title": "Kembangan dua ungkapan algebra", "body": "<div class=\"sl-def\" style=\"--c:#38BDF8\"><p>Apabila melakukan kembangan dua ungkapan algebra dalam dua tanda kurungan, setiap sebutan dalam tanda kurungan pertama mesti didarabkan dengan setiap sebutan dalam tanda kurungan kedua.</p></div><p class=\"sl-p\">Misalnya, (<i>a</i> + 3)(<i>a</i> + 2) = <i>a</i>(<i>a</i> + 2) + 3(<i>a</i> + 2) = <i>a</i>² + 2<i>a</i> + 3<i>a</i> + 6 = <i>a</i>² + 5<i>a</i> + 6</p><div class=\"sl-note\"><b>Tip:</b> (<i>a</i> + <i>b</i>)(<i>a</i> + <i>b</i>) = (<i>a</i> + <i>b</i>)², (<i>a</i> − <i>b</i>)(<i>a</i> − <i>b</i>) = (<i>a</i> − <i>b</i>)², (<i>a</i> + <i>b</i>)(<i>a</i> − <i>b</i>) = <i>a</i>² − <i>b</i>²</div><div class=\"sl-note\"><b>Perhatian:</b> (<i>a</i> + <i>b</i>)(<i>a</i> + <i>b</i>) ≠ <i>a</i>² + <i>b</i>² dan (<i>a</i> − <i>b</i>)(<i>a</i> − <i>b</i>) ≠ <i>a</i>² − <i>b</i>²</div>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Segi empat sama (a + b) kali (a + b)\"><rect x=\"70\" y=\"60\" width=\"230\" height=\"230\" fill=\"#38BDF833\" stroke=\"#38BDF8\" stroke-width=\"3\"/><rect x=\"300\" y=\"60\" width=\"120\" height=\"230\" fill=\"#A78BFA33\" stroke=\"#A78BFA\" stroke-width=\"3\"/><rect x=\"70\" y=\"290\" width=\"230\" height=\"120\" fill=\"#FBBF2433\" stroke=\"#FBBF24\" stroke-width=\"3\"/><rect x=\"300\" y=\"290\" width=\"120\" height=\"120\" fill=\"#34D39933\" stroke=\"#34D399\" stroke-width=\"3\"/><text x=\"185.0\" y=\"50.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"22\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">a</tspan></text><text x=\"360.0\" y=\"50.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"22\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">b</tspan></text><text x=\"52.0\" y=\"182.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"22\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">a</tspan></text><text x=\"52.0\" y=\"357.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"22\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">b</tspan></text><text x=\"185.0\" y=\"183.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"26\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">a</tspan>²</text><text x=\"360.0\" y=\"183.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"26\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">ab</tspan></text><text x=\"185.0\" y=\"358.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"26\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">ab</tspan></text><text x=\"360.0\" y=\"358.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"26\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">b</tspan>²</text><g class=\"rv\"><text x=\"245.0\" y=\"450.0\" fill=\"#34D399\" font-family=\"Inter, sans-serif\" font-size=\"22\" font-weight=\"700\" text-anchor=\"middle\">(<tspan font-style=\"italic\">a</tspan> + <tspan font-style=\"italic\">b</tspan>)² = <tspan font-style=\"italic\">a</tspan>² + 2<tspan font-style=\"italic\">ab</tspan> + <tspan font-style=\"italic\">b</tspan>²</text></g></svg>", "full": ""}, {"sub": "2.1", "n": 4, "N": 8, "kicker": "CONTOH 2", "title": "Kembangan dua ungkapan", "body": "<p class=\"sl-p\">Kembangkan setiap ungkapan berikut.</p><ul class=\"sl-bul\" style=\"--c:#38BDF8\"><li><span>(a) (<i>y</i> + 2)(<i>y</i> − 5)</span></li><li><span>(b) (3 + 2<i>r</i>)(4 + <i>r</i>)</span></li><li><span>(c) (2<i>r</i> + 5<i>s</i>)(<i>r</i> − 3<i>s</i>)</span></li><li><span>(d) (2<i>p</i> + 3)²</span></li></ul><div class=\"sl-note\"><b>Tip:</b> Sebutan algebra disusun daripada kuasa tertinggi kepada kuasa terendah.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#38BDF8\">(a)</b> <div class=\"rv\">= <i>y</i>(<i>y</i> − 5) + 2(<i>y</i> − 5)</div><div class=\"rv\">= <i>y</i>² − 5<i>y</i> + 2<i>y</i> − 10</div><div class=\"rv\">= <i>y</i>² − 3<i>y</i> − 10</div></div><div><b style=\"color:#38BDF8\">(b)</b> <div class=\"rv\">= 12 + 3<i>r</i> + 8<i>r</i> + 2<i>r</i>²</div><div class=\"rv\">= 2<i>r</i>² + 11<i>r</i> + 12</div></div><div><b style=\"color:#38BDF8\">(c)</b> <div class=\"rv\">= 2<i>r</i>(<i>r</i> − 3<i>s</i>) + 5<i>s</i>(<i>r</i> − 3<i>s</i>)</div><div class=\"rv\">= 2<i>r</i>² − 6<i>rs</i> + 5<i>rs</i> − 15<i>s</i>²</div><div class=\"rv\">= 2<i>r</i>² − <i>rs</i> − 15<i>s</i>²</div></div><div><b style=\"color:#38BDF8\">(d)</b> <div class=\"rv\">= (2<i>p</i> + 3)(2<i>p</i> + 3)</div><div class=\"rv\">= 4<i>p</i>² + 6<i>p</i> + 6<i>p</i> + 9</div><div class=\"rv\">= 4<i>p</i>² + 12<i>p</i> + 9</div></div></div>", "full": ""}, {"sub": "2.1", "n": 5, "N": 8, "kicker": "KONSEP", "title": "Gabungan operasi termasuk kembangan", "body": "<div class=\"sl-def\" style=\"--c:#38BDF8\"><p>Penyelesaian gabungan operasi bagi ungkapan algebra mahupun sebutan algebra mestilah mematuhi hukum 'BODMAS'.</p></div><ul class=\"sl-bul\" style=\"--c:#38BDF8\"><li><span><b>B</b> = Brackets (kurungan)</span></li><li><span><b>O</b> = Order (kuasa)</span></li><li><span><b>D</b> = Division (bahagi)</span></li><li><span><b>M</b> = Multiplication (darab)</span></li><li><span><b>A</b> = Addition (tambah)</span></li><li><span><b>S</b> = Subtraction (tolak)</span></li></ul><div class=\"sl-note\"><b>Ingat:</b> Hukum Kalis Agihan digunakan apabila melakukan kembangan: <i>a</i> × (<i>b</i> + <i>c</i>) = <i>a</i> × <i>b</i> + <i>a</i> × <i>c</i></div>", "fig": "", "full": ""}, {"sub": "2.1", "n": 6, "N": 8, "kicker": "CONTOH 3", "title": "Permudahkan", "body": "<p class=\"sl-p\">Permudah.</p><ul class=\"sl-bul\" style=\"--c:#38BDF8\"><li><span>(a) (2<i>w</i> − 3)(3<i>w</i> − 1) − 5<i>w</i></span></li><li><span>(b) (<i>r</i> − 2<i>t</i>)² + 3<i>rt</i></span></li><li><span>(c) (<i>x</i> + <i>y</i>)(<i>x</i> − <i>y</i>) + <i>x</i>(<i>x</i> − 3<i>y</i>)</span></li></ul>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#38BDF8\">(a)</b> <div class=\"rv\">= 2<i>w</i>(3<i>w</i> − 1) − 3(3<i>w</i> − 1) − 5<i>w</i></div><div class=\"rv\">= 6<i>w</i>² − 2<i>w</i> − 9<i>w</i> + 3 − 5<i>w</i></div><div class=\"rv\">= 6<i>w</i>² − 16<i>w</i> + 3</div></div><div><b style=\"color:#38BDF8\">(b)</b> <div class=\"rv\">= (<i>r</i> − 2<i>t</i>)(<i>r</i> − 2<i>t</i>) + 3<i>rt</i></div><div class=\"rv\">= <i>r</i>² − 2<i>rt</i> − 2<i>rt</i> + 4<i>t</i>² + 3<i>rt</i></div><div class=\"rv\">= <i>r</i>² − <i>rt</i> + 4<i>t</i>²</div></div><div><b style=\"color:#38BDF8\">(c)</b> <div class=\"rv\">= <i>x</i>² − <i>xy</i> + <i>xy</i> − <i>y</i>² + <i>x</i>² − 3<i>xy</i></div><div class=\"rv\">= 2<i>x</i>² − 3<i>xy</i> − <i>y</i>²</div></div></div>", "full": ""}, {"sub": "2.1", "n": 7, "N": 8, "kicker": "CONTOH 4", "title": "Penyelesaian masalah", "body": "<p class=\"sl-p\">Puan Maria mempunyai sebidang permaidani yang panjangnya (2<i>r</i> − 1) meter dan lebarnya ialah (<i>r</i> + 3) meter. Hitung luas permaidani Puan Maria.</p><p class=\"sl-p\"><b>Penyelesaian:</b></p><ol class=\"sl-steps\" style=\"--c:#38BDF8\"><li class=\"rv\"><span class=\"n\">1</span><span>Luas = panjang × lebar = (2<i>r</i> − 1)(<i>r</i> + 3)</span></li><li class=\"rv\"><span class=\"n\">2</span><span>= 2<i>r</i>² + 6<i>r</i> − <i>r</i> − 3 = 2<i>r</i>² + 5<i>r</i> − 3</span></li><li class=\"rv\"><span class=\"n\">3</span><span>Maka, luas permaidani ialah (2<i>r</i>² + 5<i>r</i> − 3) meter persegi.</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Permaidani segi empat tepat\"><rect x=\"60\" y=\"120\" width=\"380\" height=\"200\" rx=\"10\" fill=\"#FBBF2422\" stroke=\"#FBBF24\" stroke-width=\"3\"/><text x=\"250.0\" y=\"100.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"22\" font-weight=\"700\" text-anchor=\"middle\">(2<tspan font-style=\"italic\">r</tspan> − 1) m</text><text x=\"475.0\" y=\"225.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"20\" font-weight=\"700\" text-anchor=\"end\">(<tspan font-style=\"italic\">r</tspan> + 3) m</text></svg>", "full": ""}, {"sub": "2.1", "n": 8, "N": 8, "kicker": "CONTOH 5", "title": "Penyelesaian masalah", "body": "<p class=\"sl-p\">Ramesh menerima wang saku sebanyak RM40 untuk (<i>y</i> − 5) hari. Setiap hari dia membelanjakan sebanyak RM(<i>x</i> − 2) untuk secawan kopi dan RM(<i>x</i> + 3) untuk mi rebus. Hitung baki wang Ramesh.</p><ol class=\"sl-steps\" style=\"--c:#38BDF8\"><li class=\"rv\"><span class=\"n\">1</span><span><b>Memahami masalah:</b> Kenal pasti jumlah harga kopi dan mi rebus.</span></li><li class=\"rv\"><span class=\"n\">2</span><span><b>Merancang strategi:</b> Tentukan jumlah perbelanjaan dalam masa (<i>y</i> − 5) hari dengan kaedah kembangan.</span></li><li class=\"rv\"><span class=\"n\">3</span><span><b>Melaksanakan strategi:</b> Menghitung baki dengan proses kembangan.</span></li><li class=\"rv\"><span class=\"n\">4</span><span><b>Membuat kesimpulan:</b> Baki wang saku. RM(45 − 2<i>xy</i> − <i>y</i> + 10<i>x</i>)</span></li></ol>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#38BDF8\">Memahami masalah</b> <div class=\"rv\">(<i>x</i> − 2) + (<i>x</i> + 3) = 2<i>x</i> + 1</div></div><div><b style=\"color:#38BDF8\">Merancang strategi</b> <div class=\"rv\">Hari × Harga</div><div class=\"rv\">= (<i>y</i> − 5)(2<i>x</i> + 1)</div><div class=\"rv\">= 2<i>xy</i> + <i>y</i> − 10<i>x</i> − 5</div></div><div><b style=\"color:#38BDF8\">Melaksanakan strategi</b> <div class=\"rv\">Wang saku − Jumlah perbelanjaan</div><div class=\"rv\">= 40 − (2<i>xy</i> + <i>y</i> − 10<i>x</i> − 5)</div><div class=\"rv\">= 45 − 2<i>xy</i> − <i>y</i> + 10<i>x</i></div></div></div>", "full": ""}, {"sub": "2.2", "n": 1, "N": 11, "kicker": "DEFINISI", "title": "Konsep faktor dan pemfaktoran", "body": "<div class=\"sl-def\" style=\"--c:#34D399\"><p><b>Pemfaktoran</b> ialah proses mengenal pasti faktor sebutan dan ungkapan algebra dan apabila didarabkan akan menghasilkan ungkapan asal. Pemfaktoran merupakan proses songsangan kepada kembangan.</p></div><p class=\"sl-p\">Misalnya, faktor bagi 5<i>q</i>: 1 × 5<i>q</i> dan 5 × <i>q</i>. Maka, faktor bagi 5<i>q</i> ialah 1, 5, <i>q</i> dan 5<i>q</i>.</p>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Kembangan dan pemfaktoran ialah proses songsang\"><text x=\"250.0\" y=\"120.0\" fill=\"#38BDF8\" font-family=\"Space Grotesk, sans-serif\" font-size=\"30\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">a</tspan>(<tspan font-style=\"italic\">b</tspan> + <tspan font-style=\"italic\">c</tspan>)</text><text x=\"250.0\" y=\"330.0\" fill=\"#FB923C\" font-family=\"Space Grotesk, sans-serif\" font-size=\"30\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">ab</tspan> + <tspan font-style=\"italic\">ac</tspan></text><path d=\"M177.2 163.9 A95.0 95.0 0 0 0 177.2 286.1\" fill=\"none\" stroke=\"#34D399\" stroke-width=\"4\" stroke-linecap=\"round\"/><path d=\"M165.4 280.7 L177.2 286.1 L174.0 273.5\" fill=\"none\" stroke=\"#34D399\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M322.8 286.1 A95.0 95.0 0 1 0 322.8 163.9\" fill=\"none\" stroke=\"#A78BFA\" stroke-width=\"4\" stroke-linecap=\"round\"/><path d=\"M334.6 169.3 L322.8 163.9 L326.0 176.5\" fill=\"none\" stroke=\"#A78BFA\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"90.0\" y=\"230.0\" fill=\"#34D399\" font-family=\"Inter, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">Kembangan</text><text x=\"410.0\" y=\"230.0\" fill=\"#A78BFA\" font-family=\"Inter, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">Pemfaktoran</text></svg>", "full": ""}, {"sub": "2.2", "n": 2, "N": 11, "kicker": "DEFINISI", "title": "Faktor sepunya dan FSTB", "body": "<div class=\"sl-def\" style=\"--c:#34D399\"><p><b>Faktor sepunya</b> ialah faktor bagi sebutan algebra yang membahagi dengan tepat dua atau lebih sebutan lain. <b>Faktor Sepunya Terbesar (FSTB)</b> ialah faktor yang terbesar antara semua faktor sepunya.</p></div><p class=\"sl-p\">Perhatikan ungkapan, 6<i>x</i> + 3 = 3(2<i>x</i> + 1). 3 ialah faktor sepunya bagi 6<i>x</i> dan 3.</p><div class=\"sl-note\"><b>Perhatian:</b> '1' ialah faktor bagi semua sebutan algebra.</div>", "fig": "", "full": ""}, {"sub": "2.2", "n": 3, "N": 11, "kicker": "CONTOH 6", "title": "Faktor sepunya", "body": "<p class=\"sl-p\">Senaraikan semua faktor sepunya bagi setiap sebutan berikut.</p><ul class=\"sl-bul\" style=\"--c:#34D399\"><li><span>(a) 4<i>m</i>, 6<i>mn</i></span></li><li><span>(b) 8<i>p</i>²<i>q</i>, 4<i>q</i>²<i>r</i>, 12<i>pqr</i></span></li></ul>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#34D399\">(a)</b> <div class=\"rv\">4<i>m</i> = 1 × 4<i>m</i> = 2 × 2<i>m</i> = 4 × <i>m</i></div><div class=\"rv\">6<i>mn</i> = 1 × 6<i>mn</i> = 2 × 3<i>mn</i> = 3 × 2<i>mn</i> = <i>m</i> × 6<i>n</i> = 2<i>m</i> × 3<i>n</i></div><div class=\"rv\">Maka, faktor sepunya bagi 4<i>m</i> dan 6<i>mn</i> ialah 1, 2, <i>m</i> dan 2<i>m</i>.</div></div><div><b style=\"color:#34D399\">(b)</b> <div class=\"rv\">8<i>p</i>²<i>q</i> = 1 × 2 × 2 × 2 × <i>p</i> × <i>p</i> × <i>q</i></div><div class=\"rv\">4<i>q</i>²<i>r</i> = 1 × 2 × 2 × <i>q</i> × <i>q</i> × <i>r</i></div><div class=\"rv\">12<i>pqr</i> = 1 × 2 × 2 × 3 × <i>p</i> × <i>q</i> × <i>r</i></div><div class=\"rv\">Faktor sepunya ialah 1, 2, 4, <i>q</i>, 2<i>q</i> dan 4<i>q</i> kerana boleh membahagi semua sebutan di atas dengan tepat.</div></div></div>", "full": ""}, {"sub": "2.2", "n": 4, "N": 11, "kicker": "CONTOH 7", "title": "FSTB dan pemfaktoran", "body": "<p class=\"sl-p\">Ungkapan algebra boleh difaktorkan dengan mencari Faktor Sepunya Terbesar (FSTB). Misalnya, 4<i>x</i> ialah FSTB bagi 8<i>x</i> dan 12<i>x</i>². Maka, 8<i>x</i> + 12<i>x</i>² boleh ditulis sebagai hasil darab dua faktor, iaitu 4<i>x</i>(2 + 3<i>x</i>). Ini dinamakan <b>pemfaktoran</b>.</p><ul class=\"sl-bul\" style=\"--c:#34D399\"><li><span>1. Tentukan FSTB bagi setiap sebutan berikut. (a) 8<i>k</i>, 12<i>km</i> (b) 6<i>x</i>²<i>y</i>, 9<i>xy</i>², 3<i>xyz</i></span></li><li><span>2. Faktorkan setiap ungkapan berikut. (a) 5<i>x</i> + 20 (b) 9<i>m</i> + 15<i>m</i>²</span></li></ul>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#34D399\">1. (a)</b> <div class=\"rv\">FSTB = 4<i>k</i></div></div><div><b style=\"color:#34D399\">1. (b)</b> <div class=\"rv\">FSTB = 3<i>xy</i></div></div><div><b style=\"color:#34D399\">2. (a)</b> <div class=\"rv\">FSTB = 5. Maka, 5(<i>x</i> + 4)</div></div><div><b style=\"color:#34D399\">2. (b)</b> <div class=\"rv\">FSTB = 3<i>m</i>. Maka, 3<i>m</i>(3 + 5<i>m</i>)</div></div></div>", "full": ""}, {"sub": "2.2", "n": 5, "N": 11, "kicker": "CONTOH 8", "title": "Beza dua kuasa dua", "body": "<div class=\"sl-def\" style=\"--c:#34D399\"><p><i>x</i>² − <i>y</i>² ialah sebutan beza kuasa dua. <i>x</i>² − <i>y</i>² boleh difaktorkan dengan beza kuasa dua sempurna. Kaedah ini hanya boleh digunakan jika kedua-dua sebutan algebra tersebut ialah kuasa dua sempurna.</p></div><p class=\"sl-p\">Faktorkan setiap ungkapan berikut.</p><ul class=\"sl-bul\" style=\"--c:#34D399\"><li><span>(a) <i>c</i>² − 1</span></li><li><span>(b) 16<i>n</i>² − 25</span></li><li><span>(c) 2<i>y</i>² − 50</span></li><li><span>(d) 3<i>k</i>² − 27</span></li></ul>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#34D399\">(a)</b> <div class=\"rv\">= <i>c</i>² − 1²</div><div class=\"rv\">= (<i>c</i> + 1)(<i>c</i> − 1)</div></div><div><b style=\"color:#34D399\">(b)</b> <div class=\"rv\">= (4<i>n</i>)² − 5²</div><div class=\"rv\">= (4<i>n</i> + 5)(4<i>n</i> − 5)</div></div><div><b style=\"color:#34D399\">(c)</b> <div class=\"rv\">= 2(<i>y</i>² − 25)</div><div class=\"rv\">= 2(<i>y</i>² − 5²)</div><div class=\"rv\">= 2(<i>y</i> + 5)(<i>y</i> − 5)</div></div><div><b style=\"color:#34D399\">(d)</b> <div class=\"rv\">= 3(<i>k</i>² − 9)</div><div class=\"rv\">= 3(<i>k</i> + 3)(<i>k</i> − 3)</div></div></div>", "full": ""}, {"sub": "2.2", "n": 6, "N": 11, "kicker": "KONSEP", "title": "Pendaraban silang", "body": "<div class=\"sl-def\" style=\"--c:#34D399\"><p>Bagi ungkapan algebra berbentuk <i>ax</i>² + <i>bx</i> + <i>c</i> dengan <i>a</i> ≠ 0 dan <i>a</i>, <i>b</i>, <i>c</i> ialah suatu integer boleh difaktorkan dengan kaedah pendaraban silang.</p></div><ol class=\"sl-steps\" style=\"--c:#34D399\"><li class=\"rv\"><span class=\"n\">1</span><span>Langkah 1: Bandingkan pekali <i>x</i>² + 7<i>x</i> + 10. Maka, <i>a</i> = 1, <i>b</i> = 7 dan <i>c</i> = 10.</span></li><li class=\"rv\"><span class=\"n\">2</span><span>Langkah 2 dan 3: Faktor bagi 10 ialah 1, 2, 5, 10. 2 dan 5 dipilih kerana menepati <i>c</i>, iaitu 2 × 5 = 10, dan menepati <i>b</i>, iaitu 2 + 5 = 7.</span></li><li class=\"rv\"><span class=\"n\">3</span><span>Langkah 4 dan 5: Lakukan darab silang. Faktor <i>x</i>² + 7<i>x</i> + 10 ialah (<i>x</i> + 2)(<i>x</i> + 5).</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Rajah pendaraban silang\"><text x=\"90.0\" y=\"110.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">x</tspan></text><text x=\"90.0\" y=\"250.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">x</tspan></text><text x=\"260.0\" y=\"110.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">+2</text><text x=\"260.0\" y=\"250.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">+5</text><text x=\"400.0\" y=\"110.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">2<tspan font-style=\"italic\">x</tspan></text><text x=\"400.0\" y=\"250.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">5<tspan font-style=\"italic\">x</tspan></text><line x1=\"115\" y1=\"115\" x2=\"235\" y2=\"240\" stroke=\"#38BDF8\" stroke-width=\"3\"/><line x1=\"115\" y1=\"240\" x2=\"235\" y2=\"115\" stroke=\"#38BDF8\" stroke-width=\"3\"/><line x1=\"320\" y1=\"70\" x2=\"320\" y2=\"330\" stroke=\"#94A3B8\" stroke-width=\"2\"/><line x1=\"40\" y1=\"290\" x2=\"470\" y2=\"290\" stroke=\"#94A3B8\" stroke-width=\"2\"/><text x=\"250.0\" y=\"186.0\" fill=\"#94A3B8\" font-family=\"Inter, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">(×)</text><text x=\"445.0\" y=\"186.0\" fill=\"#94A3B8\" font-family=\"Inter, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">(+)</text><g class=\"rv\"><text x=\"400.0\" y=\"330.0\" fill=\"#34D399\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">7<tspan font-style=\"italic\">x</tspan></text></g></svg>", "full": ""}, {"sub": "2.2", "n": 7, "N": 11, "kicker": "CONTOH 9", "title": "Pendaraban silang", "body": "<p class=\"sl-p\">Faktorkan setiap ungkapan berikut.</p><ul class=\"sl-bul\" style=\"--c:#34D399\"><li><span>(a) <i>x</i>² − 8<i>x</i> + 16</span></li><li><span>(b) <i>m</i>² − 3<i>m</i> − 10</span></li></ul><p class=\"sl-p\"><b>Penyelesaian:</b></p><ol class=\"sl-steps\" style=\"--c:#34D399\"><li class=\"rv\"><span class=\"n\">1</span><span>(a) Pendaraban faktor 16: (−4) × (−4). (−4) + (−4) = −8. Maka, <i>x</i>² − 8<i>x</i> + 16 = (<i>x</i> − 4)(<i>x</i> − 4).</span></li><li class=\"rv\"><span class=\"n\">2</span><span>(b) Pendaraban faktor 10: 2 × (−5). 2 + (−5) = −3. Maka, <i>m</i>² − 3<i>m</i> − 10 = (<i>m</i> + 2)(<i>m</i> − 5).</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Rajah pendaraban silang\"><text x=\"90.0\" y=\"110.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">m</tspan></text><text x=\"90.0\" y=\"250.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">m</tspan></text><text x=\"260.0\" y=\"110.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">+2</text><text x=\"260.0\" y=\"250.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">−5</text><text x=\"400.0\" y=\"110.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">2<tspan font-style=\"italic\">m</tspan></text><text x=\"400.0\" y=\"250.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">−5<tspan font-style=\"italic\">m</tspan></text><line x1=\"115\" y1=\"115\" x2=\"235\" y2=\"240\" stroke=\"#38BDF8\" stroke-width=\"3\"/><line x1=\"115\" y1=\"240\" x2=\"235\" y2=\"115\" stroke=\"#38BDF8\" stroke-width=\"3\"/><line x1=\"320\" y1=\"70\" x2=\"320\" y2=\"330\" stroke=\"#94A3B8\" stroke-width=\"2\"/><line x1=\"40\" y1=\"290\" x2=\"470\" y2=\"290\" stroke=\"#94A3B8\" stroke-width=\"2\"/><text x=\"250.0\" y=\"186.0\" fill=\"#94A3B8\" font-family=\"Inter, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">(×)</text><text x=\"445.0\" y=\"186.0\" fill=\"#94A3B8\" font-family=\"Inter, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">(+)</text><g class=\"rv\"><text x=\"400.0\" y=\"330.0\" fill=\"#34D399\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">−3<tspan font-style=\"italic\">m</tspan></text></g></svg>", "full": ""}, {"sub": "2.2", "n": 8, "N": 11, "kicker": "CONTOH 10", "title": "Pendaraban silang (a ≠ 1)", "body": "<p class=\"sl-p\">Faktorkan ungkapan berikut. 3<i>m</i>² + 10<i>m</i> + 8</p><p class=\"sl-p\"><b>Penyelesaian:</b></p><ol class=\"sl-steps\" style=\"--c:#34D399\"><li class=\"rv\"><span class=\"n\">1</span><span>Pendaraban faktor 8: 1 × 8, 2 × 4</span></li><li class=\"rv\"><span class=\"n\">2</span><span>Cubaan pertama: (3<i>m</i> + 2)(<i>m</i> + 4) memberikan 12<i>m</i> + 2<i>m</i> = 14<i>m</i> ✗</span></li><li class=\"rv\"><span class=\"n\">3</span><span>Cubaan kedua: (3<i>m</i> + 4)(<i>m</i> + 2) memberikan 6<i>m</i> + 4<i>m</i> = 10<i>m</i> ✓</span></li><li class=\"rv\"><span class=\"n\">4</span><span>Maka, 3<i>m</i>² + 10<i>m</i> + 8 = (3<i>m</i> + 4)(<i>m</i> + 2).</span></li></ol><div class=\"sl-note\"><b>Tip:</b> Semak jawapan dengan kaedah kembangan.</div>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Rajah pendaraban silang\"><text x=\"90.0\" y=\"110.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">3<tspan font-style=\"italic\">m</tspan></text><text x=\"90.0\" y=\"250.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\"><tspan font-style=\"italic\">m</tspan></text><text x=\"260.0\" y=\"110.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">+4</text><text x=\"260.0\" y=\"250.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">+2</text><text x=\"400.0\" y=\"110.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">4<tspan font-style=\"italic\">m</tspan></text><text x=\"400.0\" y=\"250.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">6<tspan font-style=\"italic\">m</tspan></text><line x1=\"115\" y1=\"115\" x2=\"235\" y2=\"240\" stroke=\"#38BDF8\" stroke-width=\"3\"/><line x1=\"115\" y1=\"240\" x2=\"235\" y2=\"115\" stroke=\"#38BDF8\" stroke-width=\"3\"/><line x1=\"320\" y1=\"70\" x2=\"320\" y2=\"330\" stroke=\"#94A3B8\" stroke-width=\"2\"/><line x1=\"40\" y1=\"290\" x2=\"470\" y2=\"290\" stroke=\"#94A3B8\" stroke-width=\"2\"/><text x=\"250.0\" y=\"186.0\" fill=\"#94A3B8\" font-family=\"Inter, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">(×)</text><text x=\"445.0\" y=\"186.0\" fill=\"#94A3B8\" font-family=\"Inter, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">(+)</text><g class=\"rv\"><text x=\"400.0\" y=\"330.0\" fill=\"#34D399\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">10<tspan font-style=\"italic\">m</tspan></text></g></svg>", "full": ""}, {"sub": "2.2", "n": 9, "N": 11, "kicker": "CONTOH 11", "title": "Pekali negatif", "body": "<p class=\"sl-p\">Faktorkan ungkapan berikut.</p><ul class=\"sl-bul\" style=\"--c:#34D399\"><li><span>(a) −3<i>y</i>² − 7<i>y</i> + 6</span></li><li><span>(b) −2<i>x</i>² + 5<i>x</i> + 3</span></li></ul><p class=\"sl-p\"><b>Penyelesaian:</b></p><ol class=\"sl-steps\" style=\"--c:#34D399\"><li class=\"rv\"><span class=\"n\">1</span><span>(a) Maka, −3<i>y</i>² − 7<i>y</i> + 6 = (3<i>y</i> − 2)(−<i>y</i> − 3).</span></li><li class=\"rv\"><span class=\"n\">2</span><span>(b) Maka, −2<i>x</i>² + 5<i>x</i> + 3 = (2<i>x</i> + 1)(−<i>x</i> + 3).</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Rajah pendaraban silang\"><text x=\"90.0\" y=\"110.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">3<tspan font-style=\"italic\">y</tspan></text><text x=\"90.0\" y=\"250.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">−<tspan font-style=\"italic\">y</tspan></text><text x=\"260.0\" y=\"110.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">−2</text><text x=\"260.0\" y=\"250.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">−3</text><text x=\"400.0\" y=\"110.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">2<tspan font-style=\"italic\">y</tspan></text><text x=\"400.0\" y=\"250.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">−9<tspan font-style=\"italic\">y</tspan></text><line x1=\"115\" y1=\"115\" x2=\"235\" y2=\"240\" stroke=\"#38BDF8\" stroke-width=\"3\"/><line x1=\"115\" y1=\"240\" x2=\"235\" y2=\"115\" stroke=\"#38BDF8\" stroke-width=\"3\"/><line x1=\"320\" y1=\"70\" x2=\"320\" y2=\"330\" stroke=\"#94A3B8\" stroke-width=\"2\"/><line x1=\"40\" y1=\"290\" x2=\"470\" y2=\"290\" stroke=\"#94A3B8\" stroke-width=\"2\"/><text x=\"250.0\" y=\"186.0\" fill=\"#94A3B8\" font-family=\"Inter, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">(×)</text><text x=\"445.0\" y=\"186.0\" fill=\"#94A3B8\" font-family=\"Inter, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">(+)</text><g class=\"rv\"><text x=\"400.0\" y=\"330.0\" fill=\"#34D399\" font-family=\"Space Grotesk, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">−7<tspan font-style=\"italic\">y</tspan></text></g></svg>", "full": ""}, {"sub": "2.2", "n": 10, "N": 11, "kicker": "CONTOH 12", "title": "Faktor sepunya dalam empat sebutan", "body": "<p class=\"sl-p\">Menggunakan faktor sepunya dalam empat sebutan algebra: <i>ab</i> + <i>ac</i> + <i>bd</i> + <i>cd</i> = (<i>ab</i> + <i>ac</i>) + (<i>bd</i> + <i>cd</i>) = <i>a</i>(<i>b</i> + <i>c</i>) + <i>d</i>(<i>b</i> + <i>c</i>) = (<i>b</i> + <i>c</i>)(<i>a</i> + <i>d</i>)</p><div class=\"sl-note\"><b>Tip:</b> Gabungkan sebutan yang ada faktor sepunya di dalam satu kurungan.</div><p class=\"sl-p\">Faktorkan setiap ungkapan berikut.</p><ul class=\"sl-bul\" style=\"--c:#34D399\"><li><span>(a) <i>mn</i> + 2<i>n</i> + 3<i>m</i> + 6</span></li><li><span>(b) 3<i>px</i> + 10<i>qy</i> − 6<i>py</i> − 5<i>qx</i></span></li></ul>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#34D399\">(a)</b> <div class=\"rv\">= (<i>mn</i> + 2<i>n</i>) + (3<i>m</i> + 6)</div><div class=\"rv\">= <i>n</i>(<i>m</i> + 2) + 3(<i>m</i> + 2)</div><div class=\"rv\">= (<i>n</i> + 3)(<i>m</i> + 2)</div></div><div><b style=\"color:#34D399\">(b)</b> <div class=\"rv\">= (3<i>px</i> − 6<i>py</i>) − (5<i>qx</i> − 10<i>qy</i>)</div><div class=\"rv\">= 3<i>p</i>(<i>x</i> − 2<i>y</i>) − 5<i>q</i>(<i>x</i> − 2<i>y</i>)</div><div class=\"rv\">= (<i>x</i> − 2<i>y</i>)(3<i>p</i> − 5<i>q</i>)</div></div></div>", "full": ""}, {"sub": "2.2", "n": 11, "N": 11, "kicker": "CONTOH 13", "title": "Penyelesaian masalah", "body": "<p class=\"sl-p\">Luas sebuah padang bola sepak berbentuk segi empat tepat ialah (6<i>x</i>² + 18<i>x</i>) meter persegi. Padang itu telah ditenggelami air seperti dalam rajah. Jika lebar padang itu ialah 6<i>x</i> meter dan dua kawasan yang ditenggelami air ialah segi tiga bersudut tegak yang sama saiz, berapakah luas kawasan yang tidak ditenggelami air?</p><ol class=\"sl-steps\" style=\"--c:#34D399\"><li class=\"rv\"><span class=\"n\">1</span><span><b>Memahami masalah:</b> Kenal pasti panjang padang.</span></li><li class=\"rv\"><span class=\"n\">2</span><span><b>Merancang strategi:</b> Tentukan tapak dan luas dua segi tiga.</span></li><li class=\"rv\"><span class=\"n\">3</span><span><b>Melaksanakan strategi:</b> Luas padang − Luas dua segi tiga</span></li><li class=\"rv\"><span class=\"n\">4</span><span><b>Membuat kesimpulan:</b> (3<i>x</i>² + 9<i>x</i>) m²</span></li></ol>", "fig": "<div style=\"width:100%;display:flex;flex-direction:column;gap:10px\"><svg viewBox=\"0 0 500 250\" width=\"100%\" role=\"img\" aria-label=\"Padang dengan dua kawasan segi tiga ditenggelami air\"><rect x=\"50\" y=\"20\" width=\"400\" height=\"190\" fill=\"#34D39922\" stroke=\"#34D399\" stroke-width=\"3\"/><polygon points=\"50.0,20.0 250.0,20.0 50.0,210.0\" fill=\"#38BDF833\" stroke=\"#38BDF8\" stroke-width=\"4\" stroke-linejoin=\"round\"/><polygon points=\"250.0,20.0 450.0,20.0 450.0,210.0\" fill=\"#38BDF833\" stroke=\"#38BDF8\" stroke-width=\"4\" stroke-linejoin=\"round\"/><text x=\"250.0\" y=\"240.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"22\" font-weight=\"700\" text-anchor=\"middle\">6<tspan font-style=\"italic\">x</tspan></text></svg><div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><div class=\"rv\">Panjang = <span class=\"fr\"><span>6<i>x</i>² + 18<i>x</i></span><span>6<i>x</i></span></span> = <span class=\"fr\"><span>6<i>x</i>(<i>x</i> + 3)</span><span>6<i>x</i></span></span> = <i>x</i> + 3</div><div class=\"rv\">Tapak = 6<i>x</i> ÷ 2 = 3<i>x</i>. Luas dua segi tiga = 2 × (<span class=\"fr\"><span>1</span><span>2</span></span> × 3<i>x</i> × (<i>x</i> + 3)) = 3<i>x</i>² + 9<i>x</i></div><div class=\"rv\">6<i>x</i>² + 18<i>x</i> − (3<i>x</i>² + 9<i>x</i>) = 3<i>x</i>² + 9<i>x</i></div></div></div></div>", "full": ""}, {"sub": "2.3", "n": 1, "N": 10, "kicker": "CONTOH 14", "title": "Penambahan dan penolakan ungkapan algebra", "body": "<p class=\"sl-p\">Anda telah mempelajari kembangan, pemfaktoran dan penyelesaian masalah. Cuba selesaikan gabungan operasi berikut yang melibatkan kembangan dan pemfaktoran.</p><p class=\"sl-p\">Permudah.</p><ul class=\"sl-bul\" style=\"--c:#A78BFA\"><li><span>(a) 3<i>x</i>² − 3(<i>x</i> + 6)</span></li><li><span>(b) 2<i>w</i>(<i>w</i> + 3) − 8</span></li></ul>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\">= 3<i>x</i>² − 3<i>x</i> − 18</div><div class=\"rv\">= 3(<i>x</i>² − <i>x</i> − 6)</div><div class=\"rv\">= 3(<i>x</i> − 3)(<i>x</i> + 2)</div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\">= 2<i>w</i>² + 6<i>w</i> − 8</div><div class=\"rv\">= 2(<i>w</i>² + 3<i>w</i> − 4)</div><div class=\"rv\">= 2(<i>w</i> + 4)(<i>w</i> − 1)</div></div></div>", "full": ""}, {"sub": "2.3", "n": 2, "N": 10, "kicker": "CONTOH 15", "title": "Pecahan algebra dengan penyebut yang sama", "body": "<p class=\"sl-p\">Permudah setiap yang berikut.</p><ul class=\"sl-bul\" style=\"--c:#A78BFA\"><li><span>(a) <span class=\"fr\"><span>3<i>a</i></span><span>7</span></span> + <span class=\"fr\"><span>2<i>a</i></span><span>7</span></span></span></li><li><span>(b) <span class=\"fr\"><span><i>m</i></span><span>3<i>n</i></span></span> − <span class=\"fr\"><span>4<i>m</i></span><span>3<i>n</i></span></span></span></li><li><span>(c) <span class=\"fr\"><span><i>x</i> + 3</span><span>4<i>y</i></span></span> − <span class=\"fr\"><span><i>x</i> − 2</span><span>4<i>y</i></span></span></span></li></ul><div class=\"sl-note\"><b>Ingat:</b> Tanda negatif tidak boleh berada di bahagian penyebut. (−) × (−) = +</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\">= <span class=\"fr\"><span>5<i>a</i></span><span>7</span></span></div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\">= <span class=\"fr\"><span><i>m</i> − 4<i>m</i></span><span>3<i>n</i></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>−3<i>m</i></span><span>3<i>n</i></span></span></div><div class=\"rv\">= −<span class=\"fr\"><span><i>m</i></span><span><i>n</i></span></span></div></div><div><b style=\"color:#A78BFA\">(c)</b> <div class=\"rv\">= <span class=\"fr\"><span><i>x</i> + 3 − (<i>x</i> − 2)</span><span>4<i>y</i></span></span></div><div class=\"rv\">= <span class=\"fr\"><span><i>x</i> + 3 − <i>x</i> + 2</span><span>4<i>y</i></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>5</span><span>4<i>y</i></span></span></div></div></div>", "full": ""}, {"sub": "2.3", "n": 3, "N": 10, "kicker": "CONTOH 16", "title": "Penyebut ialah gandaan penyebut yang lain", "body": "<p class=\"sl-p\">Salah satu daripada penyebutnya ialah gandaan bagi penyebut yang lain. Permudah setiap ungkapan berikut.</p><ul class=\"sl-bul\" style=\"--c:#A78BFA\"><li><span>(a) <span class=\"fr\"><span>5</span><span>6<i>p</i></span></span> − <span class=\"fr\"><span>1</span><span>3<i>p</i></span></span></span></li><li><span>(b) <span class=\"fr\"><span>3</span><span><i>mn</i></span></span> − <span class=\"fr\"><span>2<i>k</i></span><span><i>n</i></span></span></span></li></ul><div class=\"sl-note\"><b>Tip:</b> Samakan penyebutnya.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\">= <span class=\"fr\"><span>5</span><span>6<i>p</i></span></span> − <span class=\"fr\"><span>1 × 2</span><span>3<i>p</i> × 2</span></span></div><div class=\"rv\">= <span class=\"fr\"><span>5 − 2</span><span>6<i>p</i></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>3</span><span>6<i>p</i></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>1</span><span>2<i>p</i></span></span></div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\">= <span class=\"fr\"><span>3</span><span><i>mn</i></span></span> − <span class=\"fr\"><span>2<i>k</i> × <i>m</i></span><span><i>n</i> × <i>m</i></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>3 − 2<i>km</i></span><span><i>mn</i></span></span></div></div></div>", "full": ""}, {"sub": "2.3", "n": 4, "N": 10, "kicker": "CONTOH 17", "title": "Penyebut tidak mempunyai faktor sepunya", "body": "<p class=\"sl-p\">Penyebut pecahan tersebut tidak mempunyai faktor sepunya. Permudah setiap ungkapan berikut.</p><ul class=\"sl-bul\" style=\"--c:#A78BFA\"><li><span>(a) <span class=\"fr\"><span>4<i>x</i></span><span>5</span></span> − <span class=\"fr\"><span>2<i>x</i></span><span>3</span></span></span></li><li><span>(b) <span class=\"fr\"><span>3<i>a</i></span><span>4</span></span> + <span class=\"fr\"><span><i>b</i></span><span>5<i>c</i></span></span></span></li></ul>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\">= <span class=\"fr\"><span>4<i>x</i> × 3</span><span>5 × 3</span></span> − <span class=\"fr\"><span>2<i>x</i> × 5</span><span>3 × 5</span></span></div><div class=\"rv\">= <span class=\"fr\"><span>12<i>x</i> − 10<i>x</i></span><span>15</span></span></div><div class=\"rv\">= <span class=\"fr\"><span>2<i>x</i></span><span>15</span></span></div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\">= <span class=\"fr\"><span>3<i>a</i> × 5<i>c</i></span><span>4 × 5<i>c</i></span></span> + <span class=\"fr\"><span><i>b</i> × 4</span><span>5<i>c</i> × 4</span></span></div><div class=\"rv\">= <span class=\"fr\"><span>15<i>ac</i> + 4<i>b</i></span><span>20<i>c</i></span></span></div></div></div>", "full": ""}, {"sub": "2.3", "n": 5, "N": 10, "kicker": "CONTOH 18", "title": "Penyebut mempunyai faktor sepunya", "body": "<p class=\"sl-p\">Penyebut pecahan mempunyai faktor sepunya. Gunakan Gandaan Sepunya Terkecil (GSTK). Permudah setiap ungkapan berikut.</p><ul class=\"sl-bul\" style=\"--c:#A78BFA\"><li><span>(a) <span class=\"fr\"><span>1</span><span>6<i>p</i></span></span> + <span class=\"fr\"><span>3</span><span>4<i>p</i></span></span></span></li><li><span>(b) <span class=\"fr\"><span><i>n</i></span><span>2<i>r</i></span></span> − <span class=\"fr\"><span>3<i>n</i></span><span>10<i>rs</i></span></span></span></li></ul>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\">GSTK = 2<i>p</i> × 2 × 3 = 12<i>p</i></div><div class=\"rv\">= <span class=\"fr\"><span>1 × 2</span><span>6<i>p</i> × 2</span></span> + <span class=\"fr\"><span>3 × 3</span><span>4<i>p</i> × 3</span></span></div><div class=\"rv\">= <span class=\"fr\"><span>2</span><span>12<i>p</i></span></span> + <span class=\"fr\"><span>9</span><span>12<i>p</i></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>11</span><span>12<i>p</i></span></span></div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\">GSTK = 2<i>r</i> × 5<i>s</i> = 10<i>rs</i></div><div class=\"rv\">= <span class=\"fr\"><span><i>n</i> × 5<i>s</i></span><span>2<i>r</i> × 5<i>s</i></span></span> − <span class=\"fr\"><span>3<i>n</i></span><span>10<i>rs</i></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>5<i>ns</i> − 3<i>n</i></span><span>10<i>rs</i></span></span></div></div></div>", "full": ""}, {"sub": "2.3", "n": 6, "N": 10, "kicker": "KONSEP", "title": "Pendaraban dan pembahagian ungkapan algebra", "body": "<div class=\"sl-def\" style=\"--c:#A78BFA\"><p>Untuk mendarab dan membahagi ungkapan algebra, anda perlu memfaktorkan ungkapan tersebut, kemudian memansuhkannya sekiranya terdapat faktor sepunya bagi pengangka dan penyebut.</p></div><p class=\"sl-p\">Misalnya, (2<i>p</i> + 6) ÷ (<i>p</i>² − 9) boleh ditulis sebagai <span class=\"fr\"><span>2<i>p</i> + 6</span><span><i>p</i>² − 9</span></span>.</p><div class=\"sl-note\"><b>Ingat:</b> Proses ini memerlukan kemahiran pemfaktoran yang telah anda pelajari.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><div class=\"rv\"><span class=\"fr\"><span>2<i>p</i> + 6</span><span><i>p</i>² − 9</span></span> = <span class=\"fr\"><span>2(<i>p</i> + 3)</span><span>(<i>p</i> + 3)(<i>p</i> − 3)</span></span></div><div class=\"rv\">(Faktorkan pengangka dan penyebut)</div><div class=\"rv\">= <span class=\"fr\"><span>2</span><span><i>p</i> − 3</span></span></div><div class=\"rv\">(Permudah ungkapan atau sebutan yang sama jika ada)</div></div></div>", "full": ""}, {"sub": "2.3", "n": 7, "N": 10, "kicker": "CONTOH 19", "title": "Pendaraban ungkapan algebra", "body": "<p class=\"sl-p\">Permudah.</p><ul class=\"sl-bul\" style=\"--c:#A78BFA\"><li><span>(a) <span class=\"fr\"><span><i>a</i>² − 4</span><span>3<i>ab</i></span></span> × <span class=\"fr\"><span><i>b</i>²</span><span><i>a</i> + 2</span></span></span></li><li><span>(b) <span class=\"fr\"><span>(<i>h</i> + <i>k</i>)²</span><span>3<i>h</i> − 3<i>k</i></span></span> × <span class=\"fr\"><span>2<i>h</i> − 2<i>k</i></span><span><i>h</i>² − <i>k</i>²</span></span></span></li></ul>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\">= <span class=\"fr\"><span>(<i>a</i> + 2)(<i>a</i> − 2)</span><span>3<i>ab</i></span></span> × <span class=\"fr\"><span><i>b</i> × <i>b</i></span><span><i>a</i> + 2</span></span></div><div class=\"rv\">= <span class=\"fr\"><span><i>b</i>(<i>a</i> − 2)</span><span>3<i>a</i></span></span></div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\">= <span class=\"fr\"><span>(<i>h</i> + <i>k</i>)(<i>h</i> + <i>k</i>)</span><span>3(<i>h</i> − <i>k</i>)</span></span> × <span class=\"fr\"><span>2(<i>h</i> − <i>k</i>)</span><span>(<i>h</i> + <i>k</i>)(<i>h</i> − <i>k</i>)</span></span></div><div class=\"rv\">= <span class=\"fr\"><span>2(<i>h</i> + <i>k</i>)</span><span>3(<i>h</i> − <i>k</i>)</span></span></div></div></div>", "full": ""}, {"sub": "2.3", "n": 8, "N": 10, "kicker": "CONTOH 19", "title": "Pembahagian ungkapan algebra", "body": "<p class=\"sl-p\">Permudah.</p><ul class=\"sl-bul\" style=\"--c:#A78BFA\"><li><span>(c) <span class=\"fr\"><span>4<i>a</i></span><span><i>a</i> + 3<i>b</i></span></span> ÷ <span class=\"fr\"><span>2<i>ab</i></span><span>5<i>a</i> + 15<i>b</i></span></span></span></li><li><span>(d) <span class=\"fr\"><span><i>m</i>² − <i>n</i>²</span><span>6<i>m</i> − 3<i>n</i></span></span> ÷ <span class=\"fr\"><span>(<i>m</i> − <i>n</i>)²</span><span>4<i>m</i> − 2<i>n</i></span></span></span></li></ul><div class=\"sl-note\"><b>Ingat:</b> <span class=\"fr\"><span>1</span><span><i>x</i></span></span> ÷ <span class=\"fr\"><span>1</span><span><i>x</i></span></span>: salingan <span class=\"fr\"><span>1</span><span><i>x</i></span></span> adalah <span class=\"fr\"><span><i>x</i></span><span>1</span></span> dan tukarkan operasi ÷ kepada ×.</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#A78BFA\">(c)</b> <div class=\"rv\">= <span class=\"fr\"><span>4<i>a</i></span><span><i>a</i> + 3<i>b</i></span></span> × <span class=\"fr\"><span>5(<i>a</i> + 3<i>b</i>)</span><span>2<i>ab</i></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>20<i>a</i></span><span>2<i>ab</i></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>10</span><span><i>b</i></span></span></div></div><div><b style=\"color:#A78BFA\">(d)</b> <div class=\"rv\">= <span class=\"fr\"><span>(<i>m</i> + <i>n</i>)(<i>m</i> − <i>n</i>)</span><span>3(2<i>m</i> − <i>n</i>)</span></span> × <span class=\"fr\"><span>2(2<i>m</i> − <i>n</i>)</span><span>(<i>m</i> − <i>n</i>)(<i>m</i> − <i>n</i>)</span></span></div><div class=\"rv\">= <span class=\"fr\"><span>2(<i>m</i> + <i>n</i>)</span><span>3(<i>m</i> − <i>n</i>)</span></span></div></div></div>", "full": ""}, {"sub": "2.3", "n": 9, "N": 10, "kicker": "CONTOH 20", "title": "Gabungan operasi ungkapan algebra", "body": "<p class=\"sl-p\">Selesaikan gabungan operasi berikut.</p><ul class=\"sl-bul\" style=\"--c:#A78BFA\"><li><span>(a) <span class=\"fr\"><span>3</span><span>4<i>b</i></span></span>(8<i>a</i> + 12<i>b</i>) + <span class=\"fr\"><span><i>a</i></span><span><i>b</i></span></span></span></li><li><span>(b) <span class=\"fr\"><span>4<i>k</i>² − 4<i>k</i> + 1</span><span>(2<i>k</i> + 1)(2<i>k</i> − 1)</span></span></span></li></ul>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#A78BFA\">(a)</b> <div class=\"rv\">= <span class=\"fr\"><span>3</span><span>4<i>b</i></span></span> × 4(2<i>a</i> + 3<i>b</i>) + <span class=\"fr\"><span><i>a</i></span><span><i>b</i></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>6<i>a</i> + 9<i>b</i></span><span><i>b</i></span></span> + <span class=\"fr\"><span><i>a</i></span><span><i>b</i></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>7<i>a</i> + 9<i>b</i></span><span><i>b</i></span></span></div></div><div><b style=\"color:#A78BFA\">(b)</b> <div class=\"rv\">= <span class=\"fr\"><span>(2<i>k</i> − 1)(2<i>k</i> − 1)</span><span>(2<i>k</i> + 1)(2<i>k</i> − 1)</span></span></div><div class=\"rv\">= <span class=\"fr\"><span>2<i>k</i> − 1</span><span>2<i>k</i> + 1</span></span></div></div></div>", "full": ""}, {"sub": "2.3", "n": 10, "N": 10, "kicker": "CONTOH 20", "title": "Gabungan operasi ungkapan algebra (sambungan)", "body": "<p class=\"sl-p\">Selesaikan gabungan operasi berikut.</p><ul class=\"sl-bul\" style=\"--c:#A78BFA\"><li><span>(c) <span class=\"fr\"><span>10<i>m</i> − 15<i>m</i>²</span><span>6<i>n</i>² − 18<i>n</i></span></span> × <span class=\"fr\"><span><i>n</i></span><span><i>m</i></span></span></span></li><li><span>(d) <span class=\"fr\"><span><i>p</i> − <i>q</i></span><span>2<i>p</i> + <i>q</i></span></span> ÷ <span class=\"fr\"><span>(<i>p</i> − <i>q</i>)²</span><span>6<i>p</i> + 3<i>q</i></span></span></span></li></ul><div class=\"sl-note\"><b>Perhatian:</b> Faktorkan dua, tiga dan empat sebutan. Contoh: <i>x</i>² − 16 = (<i>x</i> + 4)(<i>x</i> − 4), <i>x</i>² − 4<i>x</i> − 21 = (<i>x</i> − 7)(<i>x</i> + 3)</div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:10px;font-size:19px;line-height:1.45\"><div><b style=\"color:#A78BFA\">(c)</b> <div class=\"rv\">= <span class=\"fr\"><span>5<i>m</i>(2 − 3<i>m</i>)</span><span>6<i>n</i>(<i>n</i> − 3)</span></span> × <span class=\"fr\"><span><i>n</i></span><span><i>m</i></span></span></div><div class=\"rv\">= <span class=\"fr\"><span>5(2 − 3<i>m</i>)</span><span>6(<i>n</i> − 3)</span></span></div></div><div><b style=\"color:#A78BFA\">(d)</b> <div class=\"rv\">= <span class=\"fr\"><span><i>p</i> − <i>q</i></span><span>2<i>p</i> + <i>q</i></span></span> × <span class=\"fr\"><span>3(2<i>p</i> + <i>q</i>)</span><span>(<i>p</i> − <i>q</i>)(<i>p</i> − <i>q</i>)</span></span></div><div class=\"rv\">= <span class=\"fr\"><span>3</span><span><i>p</i> − <i>q</i></span></span></div></div></div>", "full": ""}];
